import re


def apply_case(orig, new_word):
    res = []
    for i, char in enumerate(new_word):
        if char.isalpha():
            ref_idx = min(i, len(orig) - 1)
            if orig[ref_idx].isupper():
                res.append(char.upper())
            else:
                res.append(char.lower())
        else:
            res.append(char)
    return "".join(res)


def transform_word(word):
    lower_w = word.lower()

    if lower_w == "you":
        return apply_case(word, "yeh")
    if lower_w == "to":
        return apply_case(word, "ter")
    if lower_w == "and":
        return apply_case(word, "an'")
    if lower_w == "me":
        return apply_case(word, "meh")

    if len(word) > 2:
        chars = list(word)
        if chars[0].lower() == "h":
            chars[0] = "'"
        if chars[-1].lower() in "ftdg":
            chars[-1] = "'"
        return "".join(chars)

    return word


def transform_quote(quote):
    tokens = re.findall(r"[A-Za-z]+(?:[-'][A-Za-z]+)+|[A-Za-z]+|[^A-Za-z]+", quote)

    out = []
    for token in tokens:
        if re.fullmatch(r"[A-Za-z]+", token):
            out.append(transform_word(token))
        else:
            out.append(token)

    return "".join(out)


n = int(input())
for i in range(n):
    line = input()
    parts = line.split('"')

    is_hagrid = any(
        re.search(r"\bHagrid\b", parts[j]) for j in range(0, len(parts), 2)
    )

    if is_hagrid:
        for j in range(1, len(parts), 2):
            parts[j] = transform_quote(parts[j])

    print('"'.join(parts))
